// Nimmt die Apify-Antwort (Array aus Firmen-Datensätzen) und gibt
// pro Firma ein eigenes n8n-Item zurück ("Split Out je Firma").
const input = $input.all();
const output = [];

for (const entry of input) {
  const data = entry.json;
  if (Array.isArray(data)) {
    for (const place of data) {
      output.push({ json: place });
    }
  } else if (Array.isArray(data.data)) {
    for (const place of data.data) {
      output.push({ json: place });
    }
  } else {
    output.push({ json: data });
  }
}

return output;

// Vergleicht jede Firma mit den bereits in Google Sheets vorhandenen
// Leads (anhand der Website) und markiert Dubletten.
const existingItems = $('Google Sheets: Bestehende Leads lesen').all();
const existingWebsites = existingItems
  .map(i => (i.json['Website'] || '').toString().trim().toLowerCase())
  .filter(w => w.length > 0);

return $input.all().map(item => {
  const website = (item.json.website || '').toString().trim().toLowerCase();
  item.json.isDuplicate = website.length > 0 && existingWebsites.includes(website);
  return item;
});

