// Extrahiert Lead-Score + Zusammenfassung aus der OpenAI-Antwort und
// verbindet sie wieder mit den ursprünglichen Firmendaten.
const results = [];
const scoreResponses = $input.all();
const companies = $('Dublette prüfen').all().filter(i => i.json.isDuplicate !== true);

for (let i = 0; i < scoreResponses.length; i++) {
  const company = companies[i] ? companies[i].json : {};
  let score = null;
  let summary = '';
  try {
    const content = scoreResponses[i].json.choices[0].message.content;
    const parsed = JSON.parse(content);
    score = parsed.score;
    summary = parsed.summary;
  } catch (e) {
    summary = 'Automatische Bewertung fehlgeschlagen';
  }

  results.push({
    json: {
      ...company,
      leadScore: score,
      notiz: summary,
    },
  });
}

return results;

