// Extrahiert Betreff + Text der generierten Erstmail und hängt sie an
// die Firmendaten an, damit der Gmail-Node sie versenden kann.
const results = [];
const mailResponses = $input.all();
const companies = $('Lead-Score parsen').all();

for (let i = 0; i < mailResponses.length; i++) {
  const company = companies[i] ? companies[i].json : {};
  let betreff = 'Ihr Aufzug - unverbindliches Angebot';
  let text = '';
  try {
    const content = mailResponses[i].json.choices[0].message.content;
    const parsed = JSON.parse(content);
    betreff = parsed.betreff;
    text = parsed.text;
  } catch (e) {
    text = '';
  }

  results.push({
    json: {
      ...company,
      betreff,
      mailText: text,
    },
  });
}

return results;
